import React, { useRef, useState } from "react";
import emailjs from "@emailjs/browser";
import { AnimatePresence, motion } from "framer-motion";
import { CONTACT_CARDS } from "../../data/portfolio";
import SectionReveal from "../common/SectionReveal";
import { StaggerGroup, StaggerItem } from "../common/StaggerGroup";
import MagneticButton from "../ui/MagneticButton";
import GlassCard from "../ui/GlassCard";
import { Section, SectionHeader, Container } from "../ui/Section";

const SERVICE_ID = process.env.REACT_APP_EMAILJS_SERVICE_ID || "service_0wgu52u";
const TEMPLATE_ID = process.env.REACT_APP_EMAILJS_TEMPLATE_ID || "template_dmqyceo";
const PUBLIC_KEY = process.env.REACT_APP_EMAILJS_PUBLIC_KEY || "ugIp_KbdrCcjmY1d5";

const SendIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M14.22 21.94C13.04 21.94 11.37 21.1 10.05 17.14L9.33 14.98L7.17 14.26C3.21 12.94 2.38 11.27 2.38 10.09C2.38 8.92 3.21 7.24 7.17 5.91L15.66 3.08C17.78 2.37 19.55 2.58 20.64 3.66C21.73 4.74 21.94 6.52 21.23 8.64L18.4 17.13C17.07 21.1 15.4 21.94 14.22 21.94ZM7.64 7.34C4.86 8.27 3.87 9.37 3.87 10.09C3.87 10.81 4.86 11.91 7.64 12.83L10.16 13.67C10.38 13.74 10.56 13.92 10.63 14.14L11.47 16.66C12.39 19.44 13.5 20.43 14.22 20.43C14.94 20.43 16.04 19.44 16.97 16.66L19.8 8.17C20.31 6.63 20.22 5.37 19.57 4.72C18.92 4.07 17.66 3.99 16.13 4.5L7.64 7.34Z" fill="currentColor" />
    <path d="M10.11 14.71C9.92 14.71 9.73 14.64 9.58 14.49C9.29 14.2 9.29 13.72 9.58 13.43L13.16 9.84C13.45 9.55 13.93 9.55 14.22 9.84C14.51 10.13 14.51 10.61 14.22 10.9L10.64 14.49C10.5 14.64 10.3 14.71 10.11 14.71Z" fill="currentColor" />
  </svg>
);

const inputClass =
  "w-full rounded-xl border border-black/20 bg-white px-5 py-4 text-zinc-800 outline-none transition-all placeholder:text-zinc-400 focus:border-indigo-600 focus:ring-2 focus:ring-indigo-600/20 dark:border-white/15 dark:bg-white/[0.06] dark:backdrop-blur-xl dark:text-slate-100 dark:placeholder:text-slate-500 dark:focus:border-indigo-400 dark:focus:ring-indigo-400/20 dark:focus:shadow-glow-sm";

const Contact = () => {
  const form = useRef();
  const [status, setStatus] = useState("idle");
  const [errorMessage, setErrorMessage] = useState("");

  const sendEmail = (e) => {
    e.preventDefault();
    setStatus("sending");
    setErrorMessage("");

    emailjs
      .sendForm(SERVICE_ID, TEMPLATE_ID, form.current, PUBLIC_KEY)
      .then(() => {
        setStatus("success");
        form.current.reset();
      })
      .catch((error) => {
        console.error("EmailJS error:", error);
        setStatus("error");

        const message = error?.text || "";
        if (message.includes("Invalid grant") || message.includes("Gmail_API")) {
          setErrorMessage(
            "Email service needs to be reconnected. Please contact me directly at Seliyakumanayaka18@gmail.com for now."
          );
        } else {
          setErrorMessage(
            message ||
              "Failed to send message. Please email me directly at Seliyakumanayaka18@gmail.com"
          );
        }
      });
  };

  return (
    <Section id="contact">
      <SectionHeader title="Get in touch" subtitle="Contact Me" />

      <Container className="grid gap-12 lg:grid-cols-2 lg:gap-16 justify-center">
        <SectionReveal direction="left" delay={0.1}>
          <h3 className="mb-6 text-center text-lg font-semibold text-zinc-800 dark:text-slate-100">
            Talk to me
          </h3>
          <StaggerGroup className="space-y-4 max-w-sm mx-auto">
            {CONTACT_CARDS.map(({ icon, title, value, href, external }) => (
              <StaggerItem key={title}>
                <GlassCard className="text-center">
                  <motion.i
                    className={`bx ${icon} inline-block text-3xl text-indigo-600 dark:text-indigo-400`}
                    initial={{ scale: 0, rotate: -30 }}
                    whileInView={{ scale: 1, rotate: 0 }}
                    viewport={{ once: true }}
                    whileHover={{ scale: 1.2, rotate: 8 }}
                    transition={{ type: "spring", stiffness: 320, damping: 15 }}
                  />
                  <h4 className="mt-2 text-sm font-medium text-zinc-800 dark:text-slate-100">{title}</h4>
                  <p className="my-2 text-xs text-zinc-500 break-all dark:text-slate-500">{value}</p>
                  {external ? (
                    <a
                      href={href}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs font-medium text-indigo-600 hover:gap-2 transition-all dark:text-indigo-400"
                    >
                      Write me <i className="bx bx-right-arrow-alt" />
                    </a>
                  ) : (
                    <a
                      href={href}
                      className="inline-flex items-center gap-1 text-xs font-medium text-indigo-600 hover:gap-2 transition-all dark:text-indigo-400"
                    >
                      Write me <i className="bx bx-right-arrow-alt" />
                    </a>
                  )}
                </GlassCard>
              </StaggerItem>
            ))}
          </StaggerGroup>
        </SectionReveal>

        <SectionReveal direction="right" delay={0.2}>
          <h3 className="mb-6 text-center text-lg font-semibold text-zinc-800 dark:text-slate-100">
            Write me your project
          </h3>
          <form ref={form} onSubmit={sendEmail} className="max-w-md mx-auto space-y-6">
            <div className="relative">
              <label
                htmlFor="user_name"
                className="absolute -top-2.5 left-4 z-10 bg-[#fafafa] px-1.5 text-xs font-medium text-indigo-600 dark:bg-ink-950 dark:text-indigo-300"
              >
                Name
              </label>
              <input
                id="user_name"
                type="text"
                name="user_name"
                required
                placeholder="Insert your name"
                className={inputClass}
              />
            </div>

            <div className="relative">
              <label
                htmlFor="user_email"
                className="absolute -top-2.5 left-4 z-10 bg-[#fafafa] px-1.5 text-xs font-medium text-indigo-600 dark:bg-ink-950 dark:text-indigo-300"
              >
                Mail
              </label>
              <input
                id="user_email"
                type="email"
                name="user_email"
                required
                placeholder="Insert your email"
                className={inputClass}
              />
            </div>

            <div className="relative">
              <label
                htmlFor="message"
                className="absolute -top-2.5 left-4 z-10 bg-[#fafafa] px-1.5 text-xs font-medium text-indigo-600 dark:bg-ink-950 dark:text-indigo-300"
              >
                Project
              </label>
              <textarea
                id="message"
                name="message"
                rows="8"
                required
                placeholder="Write your project"
                className={`${inputClass} resize-none`}
              />
            </div>

            <AnimatePresence mode="wait">
              {status === "success" && (
                <motion.p
                  key="success"
                  initial={{ opacity: 0, y: -8, scale: 0.95 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0 }}
                  className="text-sm text-green-600 dark:text-green-400 text-center"
                >
                  Message sent successfully! I will get back to you soon.
                </motion.p>
              )}

              {status === "error" && (
                <motion.p
                  key="error"
                  initial={{ opacity: 0, y: -8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  className="text-sm text-red-600 dark:text-red-400 text-center"
                >
                  {errorMessage}
                </motion.p>
              )}
            </AnimatePresence>

            <MagneticButton
              type="submit"
              className="w-full justify-center disabled:opacity-60 disabled:cursor-not-allowed"
              disabled={status === "sending"}
            >
              {status === "sending" ? "Sending..." : "Send Message"} {status !== "sending" && <SendIcon />}
            </MagneticButton>
          </form>
        </SectionReveal>
      </Container>
    </Section>
  );
};

export default Contact;
